        <section class="cart-shell"><div class="wrap account-wrap"><div class="account-head"><div><div class="eyebrow">Customer account</div><h1 style="margin:6px 0">Hi, {{ $customer->first_name ?: 'there' }}</h1><p class="muted" style="margin:0">{{ $customer->email }}</p></div><form method="post" action="{{ $accountLogoutUrl }}">@csrf<button class="btn ghost" type="submit">Sign out</button></form></div><div class="checkout-card"><div style="display:flex;justify-content:space-between;gap:16px;align-items:center"><h2 style="margin:0">Order history</h2><a href="{{ $orderLookupUrl }}" class="muted" style="font-size:13px;font-weight:800">Guest lookup</a></div>@if($orders->count())<div style="margin-top:12px">@foreach($orders as $item)<a class="order-card" href="{{ $pathUrl('/order/'.$item->public_id) }}"><div><strong>{{ $item->order_number }}</strong><div class="muted" style="font-size:13px">{{ $item->created_at?->format('M j, Y') }} · {{ $item->items_count }} item{{ $item->items_count == 1 ? '' : 's' }}</div></div><div style="text-align:right"><div><strong>{{ $money($item->total_minor) }}</strong></div><span class="status-pill">{{ str_replace('_',' ', $item->status) }}</span></div></a>@endforeach</div>@if($orders->lastPage()>1)<div class="pagination">@for($p=1;$p<=$orders->lastPage();$p++)@if($p===$orders->currentPage())<span class="current">{{ $p }}</span>@else<a href="{{ $orders->url($p) }}">{{ $p }}</a>@endif @endfor</div>@endif @else<div class="empty" style="margin-top:18px"><strong>No orders yet</strong><div>Orders placed with {{ $customer->email }} will appear here.</div></div>@endif</div></div></section>
